/* Local-only audit surface. Generated files are excluded from Git and the build. */
import {readFile,writeFile,mkdir,copyFile} from 'node:fs/promises';
await mkdir('js/__audit__',{recursive:true});
const html=(await readFile('index.html','utf8')).replace('<head>','<head><base href="/">').replace('</body>','<script src="/js/__audit__/axe.min.js"></script><script src="/js/__audit__/boot.js"></script></body>');
await writeFile('js/__audit__/index.html',html);
await copyFile('node_modules/axe-core/axe.min.js','js/__audit__/axe.min.js');
await writeFile('js/__audit__/boot.js',`const panel=document.createElement('div');panel.id='devAudit';panel.style.cssText='position:fixed;left:0;top:0;z-index:99999;background:white;color:black;padding:0;max-width:60px;font:8px sans-serif';panel.innerHTML='<button type="button" id="runAudit" style="padding:2px;background:black;color:white;font:8px sans-serif">Run accessibility audit</button><pre id="auditResult" style="display:none">Ready</pre>';document.body.append(panel);document.addEventListener('portfolio:dialog',e=>{if(e.detail.open){const d=document.querySelector('dialog[open]');if(d)d.append(panel);}else document.body.append(panel);});new MutationObserver(()=>{const overlay=document.querySelector('dialog[open],#mobileMenu.is-open,#caseViewer.is-open,#lightbox.is-open');const parent=overlay||document.body;if(panel.parentElement!==parent)parent.append(panel);panel.removeAttribute('inert');}).observe(document.body,{subtree:true,attributes:true,attributeFilter:['class','open','aria-hidden']});document.querySelector('#runAudit').onclick=async()=>{const output=document.querySelector('#auditResult');output.textContent='Scanning…';panel.style.visibility='hidden';try{const r=await axe.run({exclude:[['#devAudit']]},{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice']}});output.textContent=JSON.stringify({violations:r.violations.map(v=>({id:v.id,impact:v.impact,help:v.help,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))})),incomplete:r.incomplete.map(v=>({id:v.id,count:v.nodes.length,nodes:v.nodes.slice(0,8).map(n=>({target:n.target,summary:n.failureSummary}))})),passes:r.passes.length},null,2);}catch(e){output.textContent=e.message;}finally{panel.style.visibility='visible';}};`);
console.log('Audit page ready at http://localhost:8000/js/__audit__/index.html?static=1');
